// ── Settings: edit these ──────────────────────────────────────────────
const SETTINGS = {
  // Free key from jooble.org/api/about. Leave '' to skip Jooble.
  jooble_api_key: '',
  // Google Jobs via SerpApi (paid beyond its free tier). Needs the SerpApi credential.
  use_serpapi: false,
  // hh.ru asks every client to identify itself with a contact email. The app sends the signed-in
  // user's email; this is only the fallback when a request arrives without one.
  fallback_contact_email: '',
  // Searched when the query names no location.
  default_countries: ['us', 'gb'],
  // Remote-only boards. Both ask for light polling, so results are cached in the workflow:
  // Jobicy at most once an hour per query, Remotive at most 4 times a day per query.
  use_jobicy: true,
  use_remotive: true,
  jobicy_cache_minutes: 60,
  remotive_cache_minutes: 360,
  // Per-search caps, to protect free quotas.
  max_adzuna_calls: 5,
  max_jooble_calls: 2,
  max_serpapi_calls: 2,
  // Whole search results, reused for the same keywords + location + remote setting.
  // Only results where every source answered are cached. Keep the entry count small: n8n saves static data on every run.
  search_cache_minutes: 360,
  search_cache_entries: 20,
};
// ─────────────────────────────────────────────────────────────────────

const body = $input.first().json.body || {};
const keywords = String(body.keywords || '').trim() || String(body.query || '').trim();
const location = String(body.location || '').trim();
// Remote-first: the app sends remote=false only when the user turns "Remote only" off.
const remote = body.remote !== false && body.remote !== 'false';

const COUNTRIES = {
  us: ['us', 'usa', 'u.s.', 'united states', 'america'], ca: ['canada'], mx: ['mexico'], br: ['brazil', 'brasil'],
  ar: ['argentina'], cl: ['chile'], co: ['colombia'], pe: ['peru'],
  gb: ['uk', 'u.k.', 'united kingdom', 'great britain', 'britain', 'england', 'scotland', 'wales'], ie: ['ireland'],
  de: ['germany', 'deutschland'], fr: ['france'], nl: ['netherlands', 'holland'], be: ['belgium'], at: ['austria'],
  ch: ['switzerland'], es: ['spain'], it: ['italy'], pt: ['portugal'], pl: ['poland'], se: ['sweden'], no: ['norway'],
  dk: ['denmark'], fi: ['finland'], cz: ['czech republic', 'czechia'], ro: ['romania'], hu: ['hungary'], gr: ['greece'],
  ua: ['ukraine'], tr: ['turkey', 'turkiye'],
  ru: ['russia', 'russian federation', 'россия'], kz: ['kazakhstan'], by: ['belarus'], uz: ['uzbekistan'],
  au: ['australia'], nz: ['new zealand'],
  in: ['india'], sg: ['singapore'], ae: ['uae', 'united arab emirates', 'dubai', 'abu dhabi'], sa: ['saudi arabia', 'ksa'],
  qa: ['qatar'], jp: ['japan'], cn: ['china'], hk: ['hong kong'], kr: ['south korea', 'korea'], my: ['malaysia'],
  id: ['indonesia'], ph: ['philippines'], th: ['thailand'], vn: ['vietnam'], pk: ['pakistan'], bd: ['bangladesh'],
  lk: ['sri lanka'], il: ['israel'],
  za: ['south africa'], ng: ['nigeria'], ke: ['kenya'], eg: ['egypt'], ma: ['morocco'], gh: ['ghana'],
};
const NAMES = { us: 'United States', gb: 'United Kingdom', ae: 'United Arab Emirates', ru: 'Russia' };
const REGIONS = {
  europe: ['gb', 'de', 'fr', 'nl', 'es', 'it', 'pl', 'ie', 'se', 'pt'],
  'north america': ['us', 'ca'], americas: ['us', 'ca', 'br', 'mx'], 'latin america': ['br', 'mx', 'ar', 'co'],
  asia: ['in', 'sg', 'ae', 'jp', 'my', 'ph'], 'middle east': ['ae', 'sa', 'qa'], 'gulf': ['ae', 'sa', 'qa'],
  africa: ['za', 'ng', 'ke', 'eg'], oceania: ['au', 'nz'], apac: ['au', 'sg', 'in', 'jp'], emea: ['gb', 'de', 'ae', 'za'],
  cis: ['ru', 'kz', 'by', 'uz'],
  worldwide: ['us', 'gb', 'de', 'in', 'au'], global: ['us', 'gb', 'de', 'in', 'au'], anywhere: ['us', 'gb', 'de', 'in', 'au'],
};
const ADZUNA = new Set(['at', 'au', 'be', 'br', 'ca', 'ch', 'de', 'es', 'fr', 'gb', 'in', 'it', 'mx', 'nl', 'nz', 'pl', 'sg', 'us', 'za']);
const HH_AREA = { ru: 113, kz: 40, by: 16, uz: 97 };

// Big job-market cities typed without a country.
const CITIES = {
  london: 'gb', manchester: 'gb', birmingham: 'gb', edinburgh: 'gb', 'new york': 'us', nyc: 'us', 'san francisco': 'us',
  'los angeles': 'us', chicago: 'us', boston: 'us', seattle: 'us', austin: 'us', miami: 'us', toronto: 'ca', vancouver: 'ca',
  montreal: 'ca', 'mexico city': 'mx', 'sao paulo': 'br', 'são paulo': 'br', berlin: 'de', munich: 'de', hamburg: 'de',
  paris: 'fr', amsterdam: 'nl', brussels: 'be', vienna: 'at', zurich: 'ch', geneva: 'ch', madrid: 'es', barcelona: 'es',
  milan: 'it', rome: 'it', warsaw: 'pl', dublin: 'ie', lisbon: 'pt', stockholm: 'se', sydney: 'au', melbourne: 'au',
  brisbane: 'au', auckland: 'nz', mumbai: 'in', bangalore: 'in', bengaluru: 'in', delhi: 'in', 'new delhi': 'in',
  hyderabad: 'in', pune: 'in', chennai: 'in', gurgaon: 'in', noida: 'in', guwahati: 'in', johannesburg: 'za',
  'cape town': 'za', moscow: 'ru', 'saint petersburg': 'ru', 'st petersburg': 'ru', almaty: 'kz', minsk: 'by',
  tashkent: 'uz', riyadh: 'sa', doha: 'qa', tokyo: 'jp', osaka: 'jp', 'kuala lumpur': 'my', jakarta: 'id', manila: 'ph',
  bangkok: 'th', 'ho chi minh city': 'vn', karachi: 'pk', lahore: 'pk', dhaka: 'bd', lagos: 'ng', abuja: 'ng',
  nairobi: 'ke', cairo: 'eg', accra: 'gh', casablanca: 'ma', istanbul: 'tr', 'tel aviv': 'il', seoul: 'kr',
  shanghai: 'cn', beijing: 'cn',
};

const countryOf = (text) => {
  const t = text.trim().toLowerCase().replace(/\.$/, '');
  if (!t) return null;
  if (COUNTRIES[t]) return t;
  return Object.keys(COUNTRIES).find((code) => COUNTRIES[code].includes(t)) || null;
};

// "UK" → gb. "Berlin, Germany" → where=Berlin, de. "Europe" → region. "Berlin" → unknown country, text search only.
let countries = [];
let where = '';
const lower = location.toLowerCase();
if (!location) countries = SETTINGS.default_countries;
else if (REGIONS[lower]) countries = REGIONS[lower];
else {
  const whole = countryOf(location);
  const parts = location.split(',').map((s) => s.trim()).filter(Boolean);
  const last = parts.length > 1 ? countryOf(parts[parts.length - 1]) : null;
  const city = CITIES[(parts[0] || '').toLowerCase()];
  if (whole) countries = [whole];
  else if (last) { countries = [last]; where = parts.slice(0, -1).join(', '); }
  else if (city) { countries = [city]; where = parts[0]; }
  else where = location; // a city or area we cannot place: text-based sources only
}

const place = (cc) => (where ? `${where}, ` : '') + (NAMES[cc] || (COUNTRIES[cc] && COUNTRIES[cc][0].replace(/\b\w/g, (c) => c.toUpperCase())) || cc);
// Location-based boards: in remote mode they only return postings that mention remote work.
const remoteWhat = remote ? `${keywords} remote` : keywords;
const adzuna = countries.filter((c) => ADZUNA.has(c)).slice(0, SETTINGS.max_adzuna_calls).map((country) => ({ country, what: remoteWhat, where: remote ? '' : where }));
// hh.ru filters by area id; Moscow and St Petersburg have their own, other cities fall back to the country.
const HH_CITY = { moscow: 1, 'saint petersburg': 2, 'st petersburg': 2, 'st. petersburg': 2 };
const hh = countries.filter((c) => HH_AREA[c]).slice(0, 2).map((c) => {
  const area = (!remote && c === 'ru' && HH_CITY[where.toLowerCase()]) || HH_AREA[c];
  // schedule=remote is hh.ru's own remote-work filter; sent only in remote mode.
  return { url: `https://api.hh.ru/vacancies?text=${encodeURIComponent(keywords)}&area=${area}&per_page=50&period=30&order_by=publication_time${remote ? '&schedule=remote' : ''}` };
});
const uncovered = countries.filter((c) => !ADZUNA.has(c) && !HH_AREA[c]);
// Remote boards cover every country, so in remote mode Jooble/Google Jobs are only a fallback when nothing else runs.
const remoteBoards = remote && (SETTINGS.use_jobicy || SETTINGS.use_remotive);
const textTargets = remoteBoards ? [] : uncovered.length ? uncovered.map(place) : countries.length ? [] : [where];
const jooble = SETTINGS.jooble_api_key ? textTargets.slice(0, SETTINGS.max_jooble_calls).map((loc) => ({ keywords: remoteWhat, location: loc })) : [];
const serpapi = SETTINGS.use_serpapi ? textTargets.slice(0, SETTINGS.max_serpapi_calls).map((loc) => ({ q: `${remote ? 'remote ' : ''}${keywords} jobs in ${loc}` })) : [];

// ── Remote boards (Jobicy, Remotive): keyword search worldwide; the region filter runs in Rank Jobs ──
// Jobicy narrows by region slug where it has one.
const JOBICY_GEO = { us: 'usa', ca: 'canada', gb: 'uk', de: 'germany', fr: 'france', es: 'spain', nl: 'netherlands', au: 'australia', in: 'india', br: 'brazil', mx: 'mexico' };
const REGION_GEO = { europe: 'europe', 'latin america': 'latam', apac: 'apac', emea: 'emea' };
const jobicyGeo = countries.length === 1 ? JOBICY_GEO[countries[0]] || '' : REGION_GEO[lower] || '';
const remoteRequests = [];
if (remote && SETTINGS.use_jobicy) {
  remoteRequests.push({
    source: 'Jobicy',
    ttl: SETTINGS.jobicy_cache_minutes,
    url: `https://jobicy.com/api/v2/remote-jobs?count=100&tag=${encodeURIComponent(keywords)}${jobicyGeo ? `&geo=${jobicyGeo}` : ''}`,
  });
}
if (remote && SETTINGS.use_remotive) {
  remoteRequests.push({
    source: 'Remotive',
    ttl: SETTINGS.remotive_cache_minutes,
    url: `https://remotive.com/api/remote-jobs?search=${encodeURIComponent(keywords)}&limit=100`,
  });
}
// Cached responses live in workflow static data (kept between production runs).
const cache = $getWorkflowStaticData('global');
cache.remote = cache.remote || {};
const now = Date.now();
for (const [url, entry] of Object.entries(cache.remote)) {
  if (now - entry.at > 24 * 3600 * 1000) delete cache.remote[url]; // keep the cache small
}
// Same search within search_cache_minutes: answer from the cache, no source is called.
cache.search = cache.search || {};
for (const [key, entry] of Object.entries(cache.search)) {
  if (now - entry.at > SETTINGS.search_cache_minutes * 60 * 1000) delete cache.search[key];
}
const cacheKey = JSON.stringify([keywords.toLowerCase(), location.toLowerCase(), remote]);
const hit = cache.search[cacheKey];
const cachedResponse = hit ? { ...hit.response, cached_at: new Date(hit.at).toISOString() } : null;

const remoteMisses = remoteRequests.filter((r) => !cache.remote[r.url] || now - cache.remote[r.url].at > r.ttl * 60 * 1000);

// Where a remote candidate may live for the job to count ("USA" → USA, North America, Americas, Worldwide …).
const REGION_OF = {
  us: ['usa', 'united states', 'us only', 'north america', 'americas'], ca: ['canada', 'north america', 'americas'],
  mx: ['mexico', 'latam', 'latin america', 'americas'], br: ['brazil', 'latam', 'latin america', 'americas'],
  ar: ['argentina', 'latam', 'latin america', 'americas'], co: ['colombia', 'latam', 'latin america', 'americas'],
  gb: ['uk', 'united kingdom', 'europe', 'emea'], ie: ['ireland', 'europe', 'emea'],
  au: ['australia', 'apac', 'oceania'], nz: ['new zealand', 'apac', 'oceania'],
  in: ['india', 'asia', 'apac'], sg: ['singapore', 'asia', 'apac'], jp: ['japan', 'asia', 'apac'], ph: ['philippines', 'asia', 'apac'],
  my: ['malaysia', 'asia', 'apac'], id: ['indonesia', 'asia', 'apac'], pk: ['pakistan', 'asia', 'apac'], vn: ['vietnam', 'asia', 'apac'],
  ae: ['uae', 'united arab emirates', 'middle east', 'emea'], sa: ['saudi', 'middle east', 'emea'], qa: ['qatar', 'middle east', 'emea'],
  za: ['south africa', 'africa', 'emea'], ng: ['nigeria', 'africa', 'emea'], ke: ['kenya', 'africa', 'emea'], eg: ['egypt', 'africa', 'emea'],
  ru: ['russia', 'cis'], kz: ['kazakhstan', 'cis'], by: ['belarus', 'cis'], uz: ['uzbekistan', 'cis'],
};
const EUROPE = ['de', 'fr', 'nl', 'be', 'at', 'ch', 'es', 'it', 'pt', 'pl', 'se', 'no', 'dk', 'fi', 'cz', 'ro', 'hu', 'gr', 'ua', 'tr'];
for (const cc of EUROPE) REGION_OF[cc] = [(COUNTRIES[cc] || [cc])[0], 'europe', 'emea', 'eu'];
const accept = new Set(['worldwide', 'anywhere', 'global', 'remote']);
for (const cc of countries) for (const term of REGION_OF[cc] || []) accept.add(term);
// No location typed: every remote job counts.
const remoteAccept = location ? [...accept] : [];

// Daily third-party call counter, reported by the API Usage webhook. Resets at 00:00 UTC.
const countCalls = (calls) => {
  const data = $getWorkflowStaticData('global');
  const day = new Date().toISOString().slice(0, 10);
  if (!data.usage || data.usage.day !== day) data.usage = { day, calls: {} };
  for (const [source, n] of Object.entries(calls)) if (n) data.usage.calls[source] = (data.usage.calls[source] || 0) + n;
};
if (keywords && !cachedResponse) {
  countCalls({
    Adzuna: adzuna.length,
    'hh.ru': hh.length,
    Jooble: jooble.length,
    SerpApi: serpapi.length,
    Jobicy: remoteMisses.filter((r) => r.source === 'Jobicy').length,
    Remotive: remoteMisses.filter((r) => r.source === 'Remotive').length,
  });
}

const warnings = [];
if (textTargets.length && !jooble.length && !serpapi.length) {
  warnings.push(`No free source covers "${textTargets.join(', ')}". Add a Jooble key or enable SerpApi in Plan Job Sources.`);
}

return [{
  json: {
    valid: !!keywords,
    message: 'Enter keywords to search for.',
    keywords,
    location,
    remote,
    countries,
    adzuna,
    hh,
    jooble,
    serpapi,
    remote_requests: remoteRequests,
    remote_misses: remoteMisses,
    remote_accept: remoteAccept,
    jooble_api_key: SETTINGS.jooble_api_key,
    contact_email: String(body.user_email || '').trim() || SETTINGS.fallback_contact_email,
    warnings,
    cache_key: cacheKey,
    cached_response: cachedResponse,
    search_cache_entries: SETTINGS.search_cache_entries,
  },
}];

// Store fresh remote-board results in the workflow cache, trimmed to what Rank Jobs needs.
// Jobicy and Remotive ask clients to poll sparingly; the TTLs in Plan Job Sources decide when to refetch.
const requests = $('Remote Board Requests').all().map((i) => i.json);
const cache = $getWorkflowStaticData('global');
cache.remote = cache.remote || {};
const warnings = [];

const text = (s, max = 1500) =>
  String(s || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;|&#x27;|&#8217;/g, "'")
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#\d+;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, max);

const normalize = (source, res) => {
  if (source === 'Jobicy') {
    return (res.jobs || []).map((j) => ({
      id: `jobicy:${j.id}`,
      title: text(j.jobTitle, 200),
      company: text(j.companyName, 200),
      allowed: text(j.jobGeo, 200),
      description: text(j.jobDescription || j.jobExcerpt),
      url: j.url || '',
      posted_at: j.pubDate || '',
    }));
  }
  return (res.jobs || []).map((j) => ({
    id: `remotive:${j.id}`,
    title: text(j.title, 200),
    company: text(j.company_name, 200),
    allowed: text(j.candidate_required_location, 200),
    description: text(j.description),
    url: j.url || '',
    posted_at: j.publication_date || '',
  }));
};

$input.all().forEach((item, i) => {
  const req = requests[i];
  if (!req) return;
  const res = item.json;
  if (res.error || !Array.isArray(res.jobs)) {
    const msg = res.error ? res.error.message || res.error : 'unexpected response';
    warnings.push(`${req.source}: ${String(msg).slice(0, 160)}`);
    return;
  }
  cache.remote[req.url] = { at: Date.now(), source: req.source, jobs: normalize(req.source, res) };
});

return [{ json: { remote_warnings: warnings } }];

// Merge every source, keep only relevant, recent postings from real employers, newest first.
const plan = $('Plan Job Sources').first().json;
const warnings = [...plan.warnings];
const MAX_AGE_DAYS = 30;
const MAX_RESULTS = 60;

const responses = (node) => {
  try {
    return $(node).all().map((i) => i.json);
  } catch (e) {
    return []; // source not used for this search
  }
};
const clean = (s) =>
  String(s || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;|&#x27;/g, "'")
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();
const failed = (res, label) => {
  const msg = res.error ? res.error.message || res.error : res.display || res.exception || (res.errors && JSON.stringify(res.errors[0]));
  if (msg && !/hasn't returned any results/i.test(String(msg))) warnings.push(`${label}: ${String(msg).slice(0, 200)}`);
  return !!msg;
};

const jobs = [];
// Remote boards first, so their entry wins when the same job is also on a location board.
const cache = $getWorkflowStaticData('global');
const remoteCache = cache.remote || {};
try {
  warnings.push(...$('Cache Remote Results').first().json.remote_warnings);
} catch (e) {
  // every remote board was served from cache
}
for (const req of plan.remote_requests || []) {
  const entry = remoteCache[req.url];
  if (!entry) continue;
  for (const j of entry.jobs) {
    jobs.push({ ...j, location: `Remote · ${j.allowed || 'Anywhere'}`, source: req.source, remote: true });
  }
}
for (const res of responses('Adzuna Job Search')) {
  if (failed(res, 'Adzuna')) continue;
  for (const j of res.results || []) {
    jobs.push({
      id: j.id ? `adzuna:${j.id}` : undefined,
      title: clean(j.title),
      company: clean(j.company && j.company.display_name),
      location: clean(j.location && j.location.display_name),
      description: clean(j.description),
      url: j.redirect_url || '',
      posted_at: j.created || '',
      source: 'Adzuna',
    });
  }
}
for (const res of responses('hh.ru Job Search')) {
  if (failed(res, 'hh.ru')) continue;
  for (const j of res.items || []) {
    jobs.push({
      id: j.id ? `hh:${j.id}` : undefined,
      title: clean(j.name),
      company: clean(j.employer && j.employer.name),
      location: clean(j.area && j.area.name),
      description: clean([j.snippet && j.snippet.requirement, j.snippet && j.snippet.responsibility].filter(Boolean).join(' ')),
      url: j.alternate_url || '',
      posted_at: j.published_at || '',
      source: 'hh.ru',
      remote: plan.remote, // searched with schedule=remote
    });
  }
}
for (const res of responses('Jooble Job Search')) {
  if (failed(res, 'Jooble')) continue;
  for (const j of res.jobs || []) {
    jobs.push({
      id: j.id ? `jooble:${j.id}` : undefined,
      title: clean(j.title),
      company: clean(j.company),
      location: clean(j.location),
      description: clean(j.snippet),
      url: j.link || '',
      posted_at: j.updated || '',
      source: 'Jooble',
    });
  }
}
for (const res of responses('Google Jobs Search')) {
  if (failed(res, 'Google Jobs')) continue;
  for (const j of res.jobs_results || []) {
    const apply = (j.apply_options || []).find((o) => o && o.link);
    jobs.push({
      id: j.job_id || undefined,
      title: clean(j.title),
      company: clean(j.company_name),
      location: clean(j.location),
      description: clean(j.description),
      url: (apply && apply.link) || j.share_link || '',
      posted_at: (j.detected_extensions && j.detected_extensions.posted_at) || '',
      source: 'Google Jobs',
    });
  }
}

// ── Legitimacy and relevance ──
// Staffing agencies post on behalf of a hidden employer, so they are not a real company signal.
const AGENCY = /\b(recruit\w*|staffing|headhunt\w*|personnel services|employment agency|talent solutions|job ?board)\b/i;
const AGENCY_BRANDS = /^(hays|reed|randstad|adecco|manpower\w*|robert half|michael page|page (personnel|executive)|kelly services|harvey nash|allegis|aerotek|teksystems|kforce|insight global|jobot|cybercoders|hudson rpo)\b/i;
// Common job-scam patterns: upfront fees, chat-app hiring, too-good pay promises.
const SCAM = /(registration fee|processing fee|training fee|pay (a|the) (small )?fee|security deposit|telegram|whatsapp (us|only|me)|earn \$?\d+[k,]?\d* (per|a|\/) ?(day|hour|week)|no (interview|experience) (needed|required).{0,40}(earn|\$)|crypto (investment|trading) opportunit|work from home.{0,20}(earn|\$\d))/i;
const STOP = new Set(['job', 'jobs', 'role', 'roles', 'the', 'and', 'for', 'with', 'remote', 'hiring', 'vacancy', 'vacancies', 'opening', 'openings']);
const terms = plan.keywords.toLowerCase().split(/[^a-z0-9а-яё+#.]+/i).filter((t) => t.length >= 2 && !STOP.has(t));
const now = Date.now();
const ageDays = (raw) => {
  const text = String(raw || '').toLowerCase();
  const rel = /(\d+)\+?\s*(hour|day|week|month)s?\s+ago/.exec(text);
  if (rel) return Number(rel[1]) * { hour: 1 / 24, day: 1, week: 7, month: 30 }[rel[2]];
  const ms = Date.parse(raw);
  return Number.isNaN(ms) ? null : (now - ms) / 86_400_000;
};

let dropped = { agency: 0, scam: 0, irrelevant: 0, stale: 0, duplicate: 0, incomplete: 0, not_remote: 0, region: 0 };
const REMOTE = /(\bremote\b|work from home|\bwfh\b|home[- ]based|telecommut|work from anywhere|fully distributed|удал[её]нн|remoto|télétravail|home ?office)/i;
// Remote-board jobs name where the candidate may live; keep those open to the searched country/region.
const accept = plan.remote_accept || [];
const allowedHere = (allowed) => {
  const a = String(allowed || '').toLowerCase();
  if (!a || !accept.length) return true;
  return accept.some((term) => new RegExp(`(^|[^a-z])${term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}($|[^a-z])`).test(a));
};
const seen = new Set();
const kept = [];
for (const j of jobs) {
  if (!j.title || !j.company || !j.url) { dropped.incomplete++; continue; }
  if (AGENCY.test(j.company) || AGENCY_BRANDS.test(j.company)) { dropped.agency++; continue; }
  if (SCAM.test(`${j.title} ${j.description}`)) { dropped.scam++; continue; }
  if (plan.remote && !j.remote && !REMOTE.test(`${j.title} ${j.location} ${j.description}`)) { dropped.not_remote++; continue; }
  if (j.remote && j.allowed !== undefined && !allowedHere(j.allowed)) { dropped.region++; continue; }
  const text = `${j.title} ${j.description}`.toLowerCase();
  if (terms.length && !terms.some((t) => text.includes(t))) { dropped.irrelevant++; continue; }
  const age = ageDays(j.posted_at);
  if (age != null && age > MAX_AGE_DAYS) { dropped.stale++; continue; }
  const key = `${j.title}|${j.company}`.toLowerCase().replace(/[^a-z0-9а-яё|]/gi, '');
  if (seen.has(key)) { dropped.duplicate++; continue; }
  seen.add(key);
  kept.push({ ...j, _age: age == null ? 999 : age });
}

kept.sort((a, b) => a._age - b._age);
const result = kept.slice(0, MAX_RESULTS).map(({ _age, company, allowed, remote, ...j }) => {
  const location = plan.remote && !/^remote/i.test(j.location) ? `Remote · ${j.location || 'Anywhere'}` : j.location;
  return { ...j, location, company: { name: company, location } };
});
const response = { success: true, jobs: result, dropped, warnings, cached_at: null };

// Cache the answer for Plan Job Sources, unless a source failed (its warning was added above).
if (warnings.length === plan.warnings.length) {
  cache.search = cache.search || {};
  cache.search[plan.cache_key] = { at: Date.now(), response };
  const keys = Object.keys(cache.search).sort((a, b) => cache.search[a].at - cache.search[b].at);
  for (const key of keys.slice(0, Math.max(0, keys.length - plan.search_cache_entries))) delete cache.search[key];
}

return [{ json: response }];

