  if (!url || !html) continue;
  const emails = emailsIn(html);
  emails.forEach((e) => allEmails.add(e));

  // Structured data: schema.org Person entries.
  for (const m of html.matchAll(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)) {
    try {
      const walk = (node) => {
        if (!node || typeof node !== 'object') return;
        if (Array.isArray(node)) return node.forEach(walk);
        if (node['@type'] === 'Person' && node.name && node.jobTitle) add(String(node.name), String(node.jobTitle), url, emails);
        Object.values(node).forEach(walk);
      };
      walk(JSON.parse(m[1]));
    } catch (e) {
      // invalid JSON-LD
    }
  }

  const lines = decode(
    html
      .replace(/<(script|style|noscript|svg)[\s\S]*?<\/\1>/gi, ' ')
      .replace(/<\/?(p|div|h[1-6]|li|br|span|td|dt|dd|figcaption|strong|b|a|section|article)[^>]*>/gi, '\n')
      .replace(/<[^>]+>/g, ' ')
  ).split('\n').map((l) => l.replace(/\s+/g, ' ').trim()).filter(Boolean);

  for (let j = 0; j < lines.length; j++) {
    const line = lines[j];
    if (line.length > 160) continue;
    // Imprint style: "Geschäftsführer: Max Mustermann, Erika Musterfrau" / "CEO: Jane Carter".
    const label = /^([^:]{2,50}):\s*(.+)$/.exec(line);
    if (label && matchRole(label[1])) {
      const names = label[2].split(/\s*(?:,|;|\/|&|\bund\b|\band\b|\bet\b|\by\b|\bi\b)\s*/i);
      const valid = names.filter(isName);
      if (valid.length) {
        valid.forEach((n) => add(n, label[1], url, emails));
        continue;
      }
      // Label on its own line, names on the next: "Geschäftsführer:" / "Max Mustermann"
    }
    if (/^[^:]{2,50}:$/.test(line) && matchRole(line) && lines[j + 1]) {
      lines[j + 1].split(/\s*(?:,|;|&|\bund\b|\band\b)\s*/i).filter(isName).forEach((n) => add(n, line.slice(0, -1), url, emails));
      continue;
    }
    if (line.length > 80) continue;
    // "Jane Carter, CEO" / "Jane Carter – Founder" on one line.
    const split = line.split(/\s*[,|–—]\s*|\s+-\s+/);
    if (split.length >= 2 && isName(split[0]) && matchRole(split.slice(1).join(' '))) {
      add(split[0], split.slice(1).join(', '), url, emails);
      continue;
    }
    // Team card: a role line next to a name line.
    if (line.length <= 60 && matchRole(line)) {
      const name = [lines[j - 1], lines[j + 1]].find((l) => l && isName(l));
      if (name) add(name, line, url, emails);
    }
  }
}
if (targets.length && targets[0].url === '') warnings.push('Company website: not found');

// Merge: one entry per person across sources ("Jane Elizabeth Carter" = "Jane Carter").
const key = (name) => {
  const w = name.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^\p{L}\s]/gu, '').split(/\s+/).filter(Boolean);
  return `${w[0] || ''} ${w[w.length - 1] || ''}`;
};
const merged = new Map();
for (const p of [...prior.people, ...found]) {
  const k = key(p.name);
  const prev = merged.get(k);
  if (!prev) {
    merged.set(k, { ...p, sources: [p.source] });
    continue;
  }
  if (!prev.sources.includes(p.source)) prev.sources.push(p.source);
  prev.linkedin_url = prev.linkedin_url || p.linkedin_url;
  prev.email = prev.email || p.email || null;
  if (prev.role_guess && !p.role_guess) {
    prev.role = p.role;
    prev.title = p.title;
    prev.role_guess = false;
  }
  if (/linkedin\.com/i.test(prev.source_url || '') && p.source !== 'LinkedIn') prev.source_url = p.source_url;
}

const people = [...merged.values()].map(({ sources, source, role_guess, ...p }) => ({ ...p, email: p.email || null, source: sources.join(', ') }));
const emails = [...allEmails];
const personal = new Set(people.map((p) => p.email).filter(Boolean));
const generic = emails.filter((e) => GENERIC.test(e));
return [{
  json: {
